#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include "freertos/FreeRTOS.h"
#include "freertos/semphr.h"
#include "driver/uart.h"
#include "esp_mac.h"
#include "nvs.h"
#include "nvs_flash.h"
#include "cJSON.h"
#include "sentinel.h"
static SemaphoreHandle_t tx_lock;static uint8_t mac[6];
static void send_json(cJSON*j){char*line=cJSON_PrintUnformatted(j);if(!line)return;xSemaphoreTake(tx_lock,portMAX_DELAY);uart_write_bytes(0,line,strlen(line));uart_write_bytes(0,"\n",1);xSemaphoreGive(tx_lock);free(line);}static void answer(const char*r){cJSON*j=cJSON_CreateObject();cJSON_AddStringToObject(j,"result",r);send_json(j);cJSON_Delete(j);}
void serial_blob(const uint8_t*data,unsigned bytes,int width,int height){char h[128];int n=snprintf(h,sizeof(h),"{\"result\":\"capture_begin\",\"bytes\":%u,\"width\":%d,\"height\":%d}\n",bytes,width,height);const char*end="{\"result\":\"capture_end\"}\n";xSemaphoreTake(tx_lock,portMAX_DELAY);uart_write_bytes(0,h,n);uart_write_bytes(0,data,bytes);uart_write_bytes(0,end,strlen(end));uart_wait_tx_done(0,pdMS_TO_TICKS(15000));xSemaphoreGive(tx_lock);}
static cJSON*ap_json(unsigned id,const ap_t*a,uint32_t now){char b[18];sentinel_address(a->bssid,b);cJSON*j=cJSON_CreateObject();cJSON_AddStringToObject(j,"record","ap");cJSON_AddNumberToObject(j,"id",id);cJSON_AddStringToObject(j,"ssid",a->ssid);cJSON_AddStringToObject(j,"bssid",b);cJSON_AddNumberToObject(j,"channel",a->channel);cJSON_AddNumberToObject(j,"rssi",a->rssi);cJSON_AddStringToObject(j,"security",sentinel_security(a->security));cJSON_AddNumberToObject(j,"reports",a->reports);cJSON_AddNumberToObject(j,"age_seconds",now-a->last);return j;}
static void status(const sentinel_snapshot_t*s){char m[18];snprintf(m,sizeof(m),"%02x:%02x:%02x:%02x:%02x:%02x",mac[0],mac[1],mac[2],mac[3],mac[4],mac[5]);cJSON*j=cJSON_CreateObject();cJSON_AddStringToObject(j,"result","status");cJSON_AddStringToObject(j,"firmware","MSA-WiFi-Sentinel-0.3.1-CiberDeck");cJSON_AddStringToObject(j,"mac",m);cJSON_AddBoolToObject(j,"passive",true);cJSON_AddBoolToObject(j,"injection_enabled",false);cJSON_AddBoolToObject(j,"wifi_connected",false);cJSON_AddBoolToObject(j,"running",s->running);cJSON_AddNumberToObject(j,"channel",s->channel);cJSON_AddNumberToObject(j,"access_points",s->count);cJSON_AddNumberToObject(j,"frames",s->frames);cJSON_AddNumberToObject(j,"beacons",s->beacons);cJSON_AddNumberToObject(j,"deauth",s->deauth);cJSON_AddNumberToObject(j,"disassoc",s->disassoc);cJSON_AddNumberToObject(j,"malformed",s->malformed);cJSON_AddNumberToObject(j,"drops",s->dropped);cJSON_AddNumberToObject(j,"security_mismatches",s->security_mismatches);cJSON_AddBoolToObject(j,"baseline_set",s->baseline_set);cJSON_AddStringToObject(j,"baseline_ssid",s->baseline_set?s->baseline_ssid:"");cJSON_AddNumberToObject(j,"uptime",s->uptime);cJSON_AddNumberToObject(j,"heap",s->heap);cJSON_AddNumberToObject(j,"screen_frames",screen_frames());cJSON_AddNumberToObject(j,"page",screen_current_page());cJSON_AddNumberToObject(j,"button_presses",screen_button_presses());cJSON_AddNumberToObject(j,"button_holds",screen_button_holds());if(s->count)cJSON_AddItemToObject(j,"selected_ap",ap_json(s->selected,&s->aps[s->selected],s->uptime));send_json(j);cJSON_Delete(j);}
static void export_aps(const sentinel_snapshot_t*s){answer("aps_begin");for(unsigned i=0;i<s->count;i++){cJSON*j=ap_json(i,&s->aps[i],s->uptime);send_json(j);cJSON_Delete(j);}answer("aps_end");}
static int number(cJSON*j,const char*n){cJSON*v=cJSON_GetObjectItem(j,n);return cJSON_IsNumber(v)&&v->valuedouble==v->valueint?v->valueint:-1;}static void save_display(int p,bool i){nvs_handle_t h;if(nvs_open_from_partition("sentinel_nvs","display",NVS_READWRITE,&h)==ESP_OK){nvs_set_u8(h,"profile",p);nvs_set_u8(h,"invert",i);nvs_commit(h);nvs_close(h);}}
static void handle(char*line){cJSON*j=cJSON_Parse(line);cJSON*c=cJSON_GetObjectItem(j,"cmd");if(!cJSON_IsObject(j)||!cJSON_IsString(c)){cJSON_Delete(j);answer("invalid_command");return;}const char*cmd=c->valuestring;if(!strcmp(cmd,"status")||!strcmp(cmd,"aps")){sentinel_snapshot_t*s=malloc(sizeof(*s));if(!s)answer("low_memory");else{sentinel_snapshot(s);if(!strcmp(cmd,"status"))status(s);else export_aps(s);free(s);}}else if(!strcmp(cmd,"select"))answer(sentinel_select(number(j,"id"))?"selected":"invalid_ap");else if(!strcmp(cmd,"clear"))answer(sentinel_clear()?"cache_cleared":"busy");else if(!strcmp(cmd,"monitor")){cJSON*v=cJSON_GetObjectItem(j,"enabled");answer(cJSON_IsBool(v)&&sentinel_set_running(cJSON_IsTrue(v))?"monitor_changed":"invalid_monitor");}else if(!strcmp(cmd,"baseline")){cJSON*v=cJSON_GetObjectItem(j,"confirmed");answer(!cJSON_IsTrue(v)?"confirmation_required":sentinel_baseline_selected()?"baseline_saved":"no_selection");}else if(!strcmp(cmd,"forget_baseline"))answer(sentinel_forget_baseline()?"baseline_removed":"no_baseline");else if(!strcmp(cmd,"page")){int p=number(j,"index");if(p>=0&&p<PAGE_COUNT){screen_page(p);answer("page_set");}else answer("invalid_page");}else if(!strcmp(cmd,"display")){int p=number(j,"profile");cJSON*i=cJSON_GetObjectItem(j,"invert");if(p>=0&&p<2&&cJSON_IsBool(i)){screen_profile(p,cJSON_IsTrue(i));save_display(p,cJSON_IsTrue(i));answer("display_set");}else answer("invalid_display");}else if(!strcmp(cmd,"capture")){if(!screen_capture())answer("capture_failed");}else answer("unsupported_command");cJSON_Delete(j);}
void app_main(void){tx_lock=xSemaphoreCreateMutex();uart_config_t uart={.baud_rate=115200,.data_bits=UART_DATA_8_BITS,.parity=UART_PARITY_DISABLE,.stop_bits=UART_STOP_BITS_1,.flow_ctrl=UART_HW_FLOWCTRL_DISABLE,.source_clk=UART_SCLK_DEFAULT};ESP_ERROR_CHECK(uart_param_config(0,&uart));ESP_ERROR_CHECK(uart_driver_install(0,2048,4096,0,NULL,0));esp_read_mac(mac,ESP_MAC_WIFI_STA);ESP_ERROR_CHECK(nvs_flash_init());ESP_ERROR_CHECK(nvs_flash_init_partition("sentinel_nvs"));int profile=1;bool invert=true;nvs_handle_t h;if(nvs_open_from_partition("sentinel_nvs","display",NVS_READONLY,&h)==ESP_OK){uint8_t v;if(nvs_get_u8(h,"profile",&v)==ESP_OK&&v<2)profile=v;if(nvs_get_u8(h,"invert",&v)==ESP_OK)invert=v!=0;nvs_close(h);}screen_start(profile,invert);sentinel_start();answer("ready");char line[512];unsigned used=0;bool discard=false;uint8_t buf[128];while(1){int n=uart_read_bytes(0,buf,sizeof(buf),pdMS_TO_TICKS(100));for(int i=0;i<n;i++){if(buf[i]=='\n'){if(!discard&&used){line[used]=0;handle(line);}used=0;discard=false;}else if(!discard){if(used<sizeof(line)-1)line[used++]=buf[i];else{discard=true;used=0;}}}}}


